import "./Wither.scss";
import { useState, useEffect, type CSSProperties } from "react";

export default function Wither({
  className,
  style,
}: {
  className?: string;
  style?: CSSProperties;
}) {
  const [showFilled, setShowFilled] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setShowFilled(true), 4000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div
      className={["sushi-wither__visual", className].filter(Boolean).join(" ")}
      style={style}
      data-filled={showFilled}
    >
      <WitherOutlineSVG className="sushi-wither__outline wither-outline" />
      <img
        src={`${import.meta.env.BASE_URL}minecraft-wither.svg`}
        alt="Wither Filled"
        className="sushi-wither__filled"
      />
    </div>
  );
}

